// Normalise the form payload and reject obvious junk before spending AI tokens
const body = $('Contact form webhook').first().json.body || {};
const clean = (v, max) => String(v ?? '').trim().slice(0, max);
const lead = {
  name: clean(body.name, 120),
  email: clean(body.email, 200).toLowerCase(),
  phone: clean(body.phone, 40),
  company: clean(body.company, 160),
  message: clean(body.message, 3000),
  source: clean(body.source || 'website', 60),
};
const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.email);
if (!lead.name || !emailOk || lead.message.length < 5) {
  throw new Error('Invalid lead: name, valid email and message are required');
}
return [{ json: lead }];

