// Claude returns text; pull the JSON object out of it and fall back safely if parsing fails
const lead = $('Validate input').first().json;
const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
let ai;
try {
  ai = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (e) {
  ai = { score: 'warm', service: 'unknown', budget_signal: 'unknown',
         summary: 'AI parsing failed - review manually', reply_draft: '' };
}
const score = ['hot', 'warm', 'cold'].includes(ai.score) ? ai.score : 'warm';
return [{ json: { ...lead, ...ai, score } }];
